/**
 * Fleet-wide private-IP audit — REPORT ONLY. Never changes a VM, a config, a
 * NAT rule or a Server row.
 *
 * For every enabled node: read every VM/CT config (and the ARP table where the
 * node-agent supports it) and report
 *   - duplicate IPs: one address configured on 2+ VMs/CTs (2026-10-02: node-2
 *     had 10.20.1.101 on VMs 101, 137, 138 and 644, and a duplicated .106),
 *   - DB drift: a Server row whose ipAddress is not what its own VM's config
 *     says, or whose address is configured on a DIFFERENT VM.
 * The worker runs it at start-up and every 6 h (registerSweeps); the same code
 * backs scripts/fleet-ip-audit.ts for an on-demand read-only run.
 */
import { db } from "../lib/db";
import { pveFor } from "../lib/proxmox";
import { agentNeighbors } from "../lib/node-agent";
import { logError } from "../lib/log";
import { nodeIpInventory, localNeighbors } from "../lib/node-ip-inventory";
import { duplicatePrivateIps, type VmIpEntry } from "../lib/provision-guard";

export type NodeIpAuditFinding =
  | { kind: "duplicate"; node: string; ip: string; vmids: number[]; servers: { vmid: number; hostname: string | null }[] }
  | { kind: "drift"; node: string; serverId: string; hostname: string; vmid: number; dbIp: string; vmIps: string[] }
  | { kind: "held-by-other-vm"; node: string; serverId: string; hostname: string; vmid: number; dbIp: string; otherVmids: number[] }
  | { kind: "unreadable"; node: string; error: string };

/** Pure: findings for one node from its inventory + the DB rows that live there. */
export function auditNodeIps(
  node: string,
  entries: readonly VmIpEntry[],
  servers: readonly { id: string; hostname: string; vmid: number | null; ipAddress: string | null }[]
): NodeIpAuditFinding[] {
  const out: NodeIpAuditFinding[] = [];
  const byVmid = new Map(servers.filter((s) => s.vmid != null).map((s) => [s.vmid as number, s]));
  for (const [ip, vmids] of duplicatePrivateIps(entries)) {
    out.push({ kind: "duplicate", node, ip, vmids, servers: vmids.map((v) => ({ vmid: v, hostname: byVmid.get(v)?.hostname ?? null })) });
  }
  const entryByVmid = new Map(entries.map((e) => [e.vmid, e]));
  for (const s of servers) {
    if (s.vmid == null || !s.ipAddress) continue;
    const own = entryByVmid.get(s.vmid);
    const others = entries.filter((e) => e.vmid !== s.vmid && e.ips.includes(s.ipAddress!)).map((e) => e.vmid);
    if (others.length) out.push({ kind: "held-by-other-vm", node, serverId: s.id, hostname: s.hostname, vmid: s.vmid, dbIp: s.ipAddress, otherVmids: others });
    // Only compare private NAT addresses the VM config actually carries; a
    // dedicated public IP lives in ipconfig0 too, so a mismatch is real drift.
    if (own && own.ips.length && !own.ips.includes(s.ipAddress)) {
      out.push({ kind: "drift", node, serverId: s.id, hostname: s.hostname, vmid: s.vmid, dbIp: s.ipAddress, vmIps: own.ips });
    }
  }
  return out;
}

export function describeFinding(f: NodeIpAuditFinding): string {
  switch (f.kind) {
    case "duplicate":
      return `[${f.node}] ${f.ip} is configured on ${f.vmids.length} VMs: ${f.servers.map((s) => `${s.vmid}${s.hostname ? ` (${s.hostname})` : " (no Server row)"}`).join(", ")}`;
    case "drift":
      return `[${f.node}] ${f.hostname} (VM ${f.vmid}): DB says ${f.dbIp}, its VM config says ${f.vmIps.join(", ")}`;
    case "held-by-other-vm":
      return `[${f.node}] ${f.hostname} (VM ${f.vmid}): its DB address ${f.dbIp} is ALSO configured on VM ${f.otherVmids.join(", ")}`;
    case "unreadable":
      return `[${f.node}] could not audit: ${f.error}`;
  }
}

export async function fleetIpAudit(): Promise<NodeIpAuditFinding[]> {
  const nodes = await db.node.findMany({ where: { enabled: true } });
  const out: NodeIpAuditFinding[] = [];
  for (const n of nodes as any[]) {
    try {
      const conn = pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
      const inv = await nodeIpInventory(conn, {
        neighbors: n.isPrimary ? localNeighbors : () => agentNeighbors(n),
        neighborSource: n.isPrimary ? "local" : "node-agent",
      });
      const servers = await db.server.findMany({
        where: { nodeId: n.id, vmid: { not: null } },
        select: { id: true, hostname: true, vmid: true, ipAddress: true },
      });
      out.push(...auditNodeIps(n.name, inv.entries, servers));
    } catch (e) {
      out.push({ kind: "unreadable", node: n.name, error: String((e as Error)?.message ?? e).slice(0, 240) });
    }
  }
  return out;
}

/** Sweep entry: log every finding loudly (ErrorLog is fingerprint-deduped). */
export async function fleetIpAuditSweep(): Promise<void> {
  const findings = await fleetIpAudit();
  for (const f of findings) {
    const line = describeFinding(f);
    console.error(`[ip-audit] ${line}`);
    if (f.kind !== "unreadable") logError("fleet.ip-audit", new Error(line), { source: "sweep", kind: f.kind, node: f.node });
  }
  if (!findings.length) console.log("[ip-audit] no duplicate or drifted private IPs on any node");
}
/**
 * READ-ONLY fleet private-IP audit — the same code the worker's 6-hourly
 * `fleet-ip-audit` sweep runs (worker/ip-audit.ts). Lists every IPv4 configured
 * on more than one VM/CT of a node, and every Server row whose private IP
 * disagrees with its VM config or is also configured on another VM.
 *
 *   npx tsx scripts/fleet-ip-audit.ts [--json]
 *
 * Changes nothing. Exit 1 when anything is found, 0 when clean.
 */
import { db } from "../lib/db";
import { fleetIpAudit, describeFinding } from "../worker/ip-audit";

async function main() {
  const findings = await fleetIpAudit();
  if (process.argv.includes("--json")) console.log(JSON.stringify(findings, null, 2));
  else if (!findings.length) console.log("No duplicate or drifted private IPs on any enabled node.");
  else for (const f of findings) console.log(describeFinding(f));
  await db.$disconnect();
  process.exit(findings.length ? 1 : 0);
}

main().catch(async (e) => {
  console.error(e);
  await db.$disconnect().catch(() => {});
  process.exit(2);
});
