/**
 * Read-only private-IP inventory of ONE Proxmox node: every VM/CT config's
 * assigned IPv4 (+ MACs) and, where available, the node's live ARP table.
 *
 * WHY (2026-10-02, docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md): IPAM only
 * ever consulted `Server.ipAddress` in the DB. On node-2, VMs 101, 137, 138 and
 * the new valheim-gjjrv9 (644) were all configured with 10.20.1.101 (106 was
 * duplicated too) — orphans / drift the DB knew nothing about. The NAT forward
 * for 644's SSH port then reached VM 101 (ARP answered with 101's MAC), the
 * platform's SSH "landed" on a different customer's VM, every login failed, and
 * 644's own outbound traffic (the image pull) fought 101 for the address.
 *
 * Every function here only READS (Proxmox GETs, `ip neigh`), and the caller
 * decides what to do with the answer. A read that fails THROWS: "could not
 * prove the address is free" must never be treated as "free".
 */
import { execFile } from "node:child_process";
import { ipsFromVmConfig, macsFromVmConfig, type NeighborEntry, type VmIpEntry } from "./provision-guard";

export type PveGetter = { get: (path: string, params?: Record<string, any>) => Promise<any>; node: string };

export type NodeIpInventory = {
  node: string;
  entries: VmIpEntry[];
  /** null = no ARP evidence available (old node-agent / not readable) — recorded, never "all free". */
  neighbors: NeighborEntry[] | null;
  neighborSource: "local" | "node-agent" | "none";
};

const CONFIG_READ_CONCURRENCY = 8;

/** All qemu VMs + LXC containers on the node, each with its config's IPs/MACs. */
export async function listNodeVmIps(conn: PveGetter): Promise<VmIpEntry[]> {
  const [qemu, lxc] = await Promise.all([
    conn.get(`/nodes/${conn.node}/qemu`),
    conn.get(`/nodes/${conn.node}/lxc`).catch(() => []), // nodes with no CT support answer oddly; CTs are optional
  ]);
  const guests: { vmid: number; kind: "qemu" | "lxc"; name: string | null; status: string | null }[] = [];
  for (const v of (qemu ?? []) as any[]) {
    if (Number.isInteger(Number(v?.vmid)) && !v?.template) guests.push({ vmid: Number(v.vmid), kind: "qemu", name: v?.name ?? null, status: v?.status ?? null });
  }
  for (const v of (lxc ?? []) as any[]) {
    if (Number.isInteger(Number(v?.vmid)) && !v?.template) guests.push({ vmid: Number(v.vmid), kind: "lxc", name: v?.name ?? null, status: v?.status ?? null });
  }
  const out: VmIpEntry[] = [];
  for (let i = 0; i < guests.length; i += CONFIG_READ_CONCURRENCY) {
    const batch = guests.slice(i, i + CONFIG_READ_CONCURRENCY);
    const cfgs = await Promise.all(
      batch.map((g) =>
        conn.get(`/nodes/${conn.node}/${g.kind}/${g.vmid}/config`).catch((e: any) => {
          throw new Error(`could not read ${g.kind} ${g.vmid}'s config on ${conn.node}: ${String(e?.message ?? e).slice(0, 160)}`);
        })
      )
    );
    batch.forEach((g, j) => out.push({ ...g, ips: ipsFromVmConfig(cfgs[j]), macs: macsFromVmConfig(cfgs[j]) }));
  }
  return out;
}

/** The local host's IPv4 neighbour table (`ip -4 -j neigh show`) — the worker runs ON the primary. */
export function localNeighbors(): Promise<NeighborEntry[] | null> {
  return new Promise((resolve) => {
    execFile("ip", ["-4", "-j", "neigh", "show"], { timeout: 10_000, maxBuffer: 4 * 1024 * 1024 }, (err, stdout) => {
      if (err) return resolve(null);
      try {
        const rows = JSON.parse(stdout || "[]");
        resolve(
          (Array.isArray(rows) ? rows : []).map((r: any) => ({
            ip: String(r?.dst ?? ""),
            mac: r?.lladdr ? String(r.lladdr).toLowerCase() : null,
            state: Array.isArray(r?.state) ? r.state.join(",") : String(r?.state ?? ""),
          }))
        );
      } catch {
        resolve(null);
      }
    });
  });
}

/**
 * Inventory for a node. `neighbors` is how to read its ARP table: the local one
 * on the primary, the node-agent's /v1/net/neigh elsewhere (null when the
 * agent predates v4). VM config reads failing throws.
 */
export async function nodeIpInventory(
  conn: PveGetter,
  opts: { neighbors?: () => Promise<NeighborEntry[] | null>; neighborSource?: "local" | "node-agent" } = {}
): Promise<NodeIpInventory> {
  const entries = await listNodeVmIps(conn);
  let neighbors: NeighborEntry[] | null = null;
  if (opts.neighbors) {
    try {
      neighbors = await opts.neighbors();
    } catch (e) {
      console.warn(`[ipam] ${conn.node}: ARP table unavailable (${String((e as Error)?.message ?? e).slice(0, 160)}) — VM-config check only`);
      neighbors = null;
    }
  }
  return { node: conn.node, entries, neighbors, neighborSource: neighbors ? (opts.neighborSource ?? "local") : "none" };
}
