 */
export function isKeptSourceVm(
  cfg: Record<string, unknown> | null | undefined,
  opts: { expectedName: string | null | undefined; tagRecorded: boolean },
): { ok: boolean; reason: string } {
  if (!cfg) return { ok: false, reason: "no config" };
  if (opts.expectedName && cfg.name !== undefined && String(cfg.name) !== opts.expectedName) {
    return { ok: false, reason: `name ${String(cfg.name)} != expected ${opts.expectedName}` };
  }
  if (opts.tagRecorded && !splitTags(cfg.tags).includes(MOVED_SOURCE_TAG)) {
    return { ok: false, reason: `tag ${MOVED_SOURCE_TAG} missing` };
  }
  if (cfg.template) return { ok: false, reason: "is a template" };
  return { ok: true, reason: "name/tag match" };
}

