/** MACs a config's netN lines carry (`virtio=BC:24:11:…,bridge=vmbr1` or lxc `hwaddr=`). */
export function macsFromVmConfig(cfg: VmConfigLike | null | undefined): string[] {
  if (!cfg || typeof cfg !== "object") return [];
  const out = new Set<string>();
  for (const [k, v] of Object.entries(cfg)) {
    if (typeof v !== "string" || !/^net\d+$/.test(k)) continue;
    for (const part of v.split(",")) {
      const m = /^(?:[a-z0-9]+|hwaddr)=((?:[0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2})$/.exec(part.trim());
      if (m) out.add(m[1].toLowerCase());
    }
  }
  return [...out];
}

