import { db } from "./db";
import { freshVmidFloor, isReservedVmid } from "./proxmox";

export const VMID_HIGH_WATER_KEY = "vmid_high_water";

export async function claimVmidHighWater(floor: number): Promise<number> {
  const f = Number.isInteger(floor) && floor >= 100 ? floor : 100;
  const rows = await db.$queryRaw<{ value: string }[]>`
    INSERT INTO "Setting" ("key", "value") VALUES (${VMID_HIGH_WATER_KEY}, ${String(f)})
    ON CONFLICT ("key") DO UPDATE
      SET "value" = GREATEST(("Setting"."value")::bigint + 1, ${f}::bigint)::text
    RETURNING "value"`;
  const claimed = Number(rows?.[0]?.value);
  if (!Number.isInteger(claimed) || claimed <= 0) throw new Error(`${VMID_HIGH_WATER_KEY} returned a non-integer (${rows?.[0]?.value})`);
  // Never step into the template range; jump it once and re-claim from there.
  if (isReservedVmid(claimed)) return claimVmidHighWater(freshVmidFloor(claimed, [claimed]));
  return claimed;
}

/** Raise the mark after a vmid was used by a path that did not claim it here. */
export async function bumpVmidHighWater(vmid: number): Promise<void> {
  if (!Number.isInteger(vmid) || vmid < 100) return;
  await db.$executeRaw`
    UPDATE "Setting" SET "value" = GREATEST(("value")::bigint, ${vmid}::bigint)::text
    WHERE "key" = ${VMID_HIGH_WATER_KEY}`;
}
