export function parseReservedIps(raw: string | null | undefined): Map<string, string> {
  const out = new Map<string, string>();
  for (const line of String(raw ?? "").split(/\r?\n/)) {
    const t = line.replace(/#.*$/, "").trim();
    if (!t) continue;
    const m = /^(\S+)\s*(.*)$/.exec(t);
    if (m && isIpv4(m[1])) out.set(m[1], m[2].trim());
