/**
 * Manage the IPAM reservation list (Setting `ipam.reserved_ips`) — addresses of
 * hand-built infra VMs that IPAM must never hand out.
 *
 *   npx tsx scripts/ipam-reserve.ts list
 *   npx tsx scripts/ipam-reserve.ts add 10.20.3.103 "nxlabs-storage (VM 501, node-4)"
 *   npx tsx scripts/ipam-reserve.ts remove 10.20.3.103
 */
import { db } from "../lib/db";
import { isIpv4 } from "../lib/provision-guard";
import { IPAM_RESERVED_KEY, parseReservedIps, serializeReservedIps } from "../lib/ip-reservations";

async function main() {
  const [cmd, ip, ...rest] = process.argv.slice(2);
  const row = await db.setting.findUnique({ where: { key: IPAM_RESERVED_KEY } });
  const m = parseReservedIps(row?.value);
  if (cmd === "list" || !cmd) {
    if (!m.size) console.log("(no reserved IPs)");
    for (const [a, l] of m) console.log(`${a}  ${l}`);
  } else if (cmd === "add" || cmd === "remove") {
    if (!isIpv4(ip)) throw new Error("usage: add <ipv4> <label> | remove <ipv4>");
    if (cmd === "add") m.set(ip, rest.join(" ").trim());
    else m.delete(ip);
    const value = serializeReservedIps(m);
    await db.setting.upsert({ where: { key: IPAM_RESERVED_KEY }, create: { key: IPAM_RESERVED_KEY, value }, update: { value } });
    console.log(`${cmd === "add" ? "reserved" : "released"} ${ip}; ${m.size} reservation(s) now`);
  } else throw new Error("usage: list | add <ip> <label> | remove <ip>");
  await db.$disconnect();
}
main().catch(async (e) => { console.error(e.message ?? e); await db.$disconnect().catch(() => {}); process.exit(1); });
