/**
 * Pure rules for "a VM id, once handed out or seen, is never offered again".
 * No I/O — lib/vmid-high-water.ts persists, worker/ip-audit.ts sweeps.
 */
import { isReservedVmid, SANDBOX_VMID_MIN } from "./proxmox";

/** Ids that take part in the monotonic rule: real Proxmox ids, not the template band, reserved infra ids or sandbox ids. */
export function isCountableVmid(v: unknown): v is number {
  return typeof v === "number" && Number.isInteger(v) && v >= 100 && v < SANDBOX_VMID_MIN && !isReservedVmid(v);
}

export function highestCountableVmid(ids: Iterable<number>): number {
  let high = 0;
  for (const v of ids) if (isCountableVmid(v) && v > high) high = v;
  return high;
}

/**
 * Refuse an id for a BRAND-NEW allocation when it is at or below the effective
 * mark (max of the Setting and every recorded-used id) or already recorded as
 * used. The only exception is the retry of a Server row that already owns it.
 */
export function refuseStaleVmid(opts: {
  vmid: number;
  effectiveMark: number;
  used: ReadonlySet<number>;
