a=s.index("export async function fleetIpAudit()")
s=s[:a]+'''export type FleetAuditResult = {
  findings: NodeIpAuditFinding[];
  observed: ObservedVm[];
  /** Nodes whose VM inventory was read successfully (only these may auto-resolve alerts). */
  readNodes: { id: string; name: string }[];
};

export async function fleetIpAuditDetailed(): Promise<FleetAuditResult> {
  const nodes = await db.node.findMany({ where: { enabled: true } });
  const findings: NodeIpAuditFinding[] = [];
  const observed: ObservedVm[] = [];
  const readNodes: { id: string; name: string }[] = [];
  for (const n of nodes as any[]) {
    try {
      const conn = pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
      const inv = await nodeIpInventory(conn, {
        neighbors: n.isPrimary ? localNeighbors : () => agentNeighbors(n),
        neighborSource: n.isPrimary ? "local" : "node-agent",
      });
      const servers = await db.server.findMany({
        where: { nodeId: n.id, vmid: { not: null } },
        select: { id: true, hostname: true, vmid: true, ipAddress: true },
      });
      const moves = await db.vmMove.findMany({
        where: { sourceNodeId: n.id, status: "DONE", sourceCleanedAt: null },
        select: { sourceVmid: true, keepSourceUntil: true },
      });
      findings.push(...auditNodeIps(n.name, inv.entries, servers, moves));
      for (const e of inv.entries) observed.push({ nodeId: n.id, nodeName: n.name, vmid: e.vmid, name: e.name ?? null, status: e.status ?? null });
      readNodes.push({ id: n.id, name: n.name });
    } catch (e) {
      findings.push({ kind: "unreadable", node: n.name, error: String((e as Error)?.message ?? e).slice(0, 240) });
    }
  }
  return { findings, observed, readNodes };
}

export async function fleetIpAudit(): Promise<NodeIpAuditFinding[]> {
  return (await fleetIpAuditDetailed()).findings;
}

/**
 * VM-id bookkeeping for one sweep (rule: an id seen or handed out once is never
 * offered again). Raises `vmid_high_water` to the highest real id on any node
 * (template/reserved/sandbox ids ignored) and records every KNOWN id in the
 * retired-id list. An id on a node that the platform never assigned (no Server
 * row, move, or retired record) is returned as unknown — NOT recorded, so its
 * alert persists until `npx tsx scripts/vmid-ack.ts <id>`. The first ever run
 * baselines everything already on the fleet (hand-built infra) without alerting.
 */
export async function reconcileVmids(observed: readonly ObservedVm[]): Promise<ObservedVm[]> {
  if (!observed.length) return [];
  const [servers, moves, used, baseline] = await Promise.all([
    db.server.findMany({ where: { vmid: { not: null } }, select: { vmid: true } }),
    db.vmMove.findMany({ select: { sourceVmid: true, targetVmid: true } }),
    loadUsedVmids(),
    db.setting.findUnique({ where: { key: VMID_BASELINE_KEY } }),
  ]);
  const known = new Set<number>(used);
  for (const r of servers) if (r.vmid != null) known.add(r.vmid);
  for (const m of moves) { known.add(m.sourceVmid); known.add(m.targetVmid); }
