/**
 * Fleet sweep alerting (IP clashes, leftover VMs, unknown vmids), the IPAM
 * reservation list and the never-reuse-a-vmid rules. Pure — no DB, no Proxmox.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { auditNodeIps, desiredIpAlerts, describeFinding } from "../worker/ip-audit.ts";
import { planFleetAlerts, type DesiredAlert, type OpenAlert } from "../lib/fleet-alert-plan.ts";
import { parseReservedIps, serializeReservedIps } from "../lib/ip-reservations.ts";
import { pickFreeIp } from "../lib/ipam.ts";
import { isCountableVmid, highestCountableVmid, refuseStaleVmid, unknownVmids } from "../lib/vmid-guard.ts";

const e = (vmid: number, ips: string[], extra: Record<string, unknown> = {}) => ({ vmid, kind: "qemu", name: `vm${vmid}`, status: "stopped", ips, macs: [], tags: [] as string[], ...extra });
const N2 = { id: "n2", name: "node-2" };
const NOW = new Date("2026-10-02T12:00:00Z");

test("clash with no tracked server is WARN; with a tracked customer server it is CRITICAL", () => {
  const entries = [e(101, ["10.20.1.101"]), e(137, ["10.20.1.101"]), e(106, ["10.20.1.106"]), e(116, ["10.20.1.106"])];
  const f = auditNodeIps("node-2", entries, []);
  const a = desiredIpAlerts(N2, f);
  assert.equal(a.length, 2);
  assert.ok(a.every((x) => x.severity === "WARN" && x.dimension.startsWith("IP-CLASH:")));
  assert.match(a[0].detail, /No DB-tracked customer server/);

  const f2 = auditNodeIps("node-2", entries, [{ id: "s1", hostname: "cust-1", vmid: 137, ipAddress: "10.20.1.101" }]);
  const crit = desiredIpAlerts(N2, f2).find((x) => x.dimension === "IP-CLASH:10.20.1.101")!;
  assert.equal(crit.severity, "CRITICAL");
  assert.match(crit.detail, /cust-1/);
  assert.match(crit.detail, /101, 137/);
});

test("tracked server whose DB ip is held by another VM (no config duplicate) is one CRITICAL alert, not two", () => {
  const entries = [e(132, ["10.20.3.250"]), e(501, ["10.20.3.103"])];
  const f = auditNodeIps("node-4", entries, [{ id: "s", hostname: "cust", vmid: 132, ipAddress: "10.20.3.103" }]);
  const a = desiredIpAlerts({ id: "n4", name: "node-4" }, f).filter((x) => x.dimension === "IP-CLASH:10.20.3.103");
  assert.equal(a.length, 1);
  assert.equal(a[0].severity, "CRITICAL");
});

test("leftover: tagged or DONE-move source with no Server row; running/IP-sharing are flagged, stopped is report-only", () => {
  const entries = [
    e(101, ["10.20.1.101"], { tags: ["nxeon-moved"] }),
    e(150, ["10.20.1.150"], { tags: ["nxeon-moved"], status: "running" }),
    e(160, ["10.20.1.160"]), // untagged but a DONE move's source
    e(200, ["10.20.1.101"]), // live tracked server sharing .101
    e(300, ["10.20.1.30"], { tags: ["nxeon-moved"] }), // tracked server wrongly carrying the tag: not a leftover
  ];
  const servers = [
    { id: "a", hostname: "live", vmid: 200, ipAddress: "10.20.1.101" },
    { id: "b", hostname: "tagged-live", vmid: 300, ipAddress: "10.20.1.30" },
  ];
  const keep = new Date("2026-10-09T00:00:00Z");
  const f = auditNodeIps("node-2", entries, servers, [{ sourceVmid: 160, keepSourceUntil: keep }]);
  const lo = f.filter((x) => x.kind === "leftover") as any[];
  assert.deepEqual(lo.map((x) => x.vmid).sort(), [101, 150, 160]);
  assert.deepEqual(lo.find((x) => x.vmid === 101).sharesIpWith, [200]);
  assert.equal(lo.find((x) => x.vmid === 160).tagged, false);
  assert.match(describeFinding(lo.find((x) => x.vmid === 160)), /NOT tagged nxeon-moved.*safe to delete after 2026-10-09.*never auto-deleted/);
  const alerts = desiredIpAlerts(N2, f);
  assert.deepEqual(alerts.filter((x) => x.dimension.startsWith("LEFTOVER-VM:")).map((x) => x.dimension), ["LEFTOVER-VM:150"]);
  const clash = alerts.find((x) => x.dimension === "IP-CLASH:10.20.1.101")!;
  assert.match(clash.detail, /101 \[leftover\]/);
  assert.equal(clash.severity, "CRITICAL");
});

const D = (dimension: string, severity: "WARN" | "CRITICAL" = "WARN"): DesiredAlert => ({ nodeId: "n2", nodeName: "node-2", dimension, severity, title: `t ${dimension}`, detail: "d" });
